static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t bswap32(uint32_t x){ return __builtin_bswap32(x); }

static void sha256_block(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i=0;i<16;i++) {
        uint32_t v; memcpy(&v, block+4*i, 4); w[i]=bswap32(v);
    }
    for (int i=16;i<64;i++) {
        uint32_t s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>3);
        uint32_t s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i=0;i<64;i++) {
        uint32_t S1 = rotr(e,6)^rotr(e,11)^rotr(e,25);
        uint32_t ch = (e&f)^((~e)&g);
        uint32_t t1 = h + S1 + ch + K[i] + w[i];
        uint32_t S0 = rotr(a,2)^rotr(a,13)^rotr(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0 + maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d;
    state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t i=0;
    for (; i+64<=len; i+=64) sha256_block(state, data+i);
    uint8_t block[64];
    size_t rem = len-i;
    memcpy(block, data+i, rem);
    block[rem]=0x80;
    if (rem+1 <= 56) {
        memset(block+rem+1, 0, 56-(rem+1));
        uint64_t bits = __builtin_bswap64((uint64_t)len*8);
        memcpy(block+56, &bits, 8);
        sha256_block(state, block);
    } else {
        memset(block+rem+1, 0, 64-(rem+1));
        sha256_block(state, block);
        memset(block, 0, 56);
        uint64_t bits = __builtin_bswap64((uint64_t)len*8);
        memcpy(block+56, &bits, 8);
        sha256_block(state, block);
    }
    for (int j=0;j<8;j++) {
        uint32_t v = bswap32(state[j]);
        memcpy(out+4*j, &v, 4);
    }
}

int main() {
    size_t n = 20*1024*1024;
    uint8_t *data = malloc(n);
    memset(data, 0x5a, n);
    uint8_t out[32];
    // warmup
    sha256(data, n, out);
    struct timespec t0,t1;
    int iters=3;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for(int i=0;i<iters;i++) sha256(data, n, out);
