    double sec = (t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("time %.4f s  rate %.1f MB/s\n", sec/iters, (n/(sec/iters))/1e6);
    for(int i=0;i<32;i++) printf("%02x", out[i]);
    printf("\n");
    return 0;
}
