    /* split into independent chunks just to measure parallel SHA256 throughput */
    pthread_t th[32];
    job_t jobs[32];
    size_t chunk = n / threads;
    for (int i=0;i<threads;i++) {
        jobs[i].data = data + i*chunk;
        jobs[i].len = (i==threads-1) ? (n - i*chunk) : chunk;
    }
    /* warmup */
    for (int i=0;i<threads;i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    for (int i=0;i<threads;i++) pthread_join(th[i], NULL);

